function splitMessage(text, limit = 4000) {
  const parts = [];
  while (text.length > limit) {
    let splitPos = text.lastIndexOf('\n', limit);
    if (splitPos === -1 || splitPos < 100) {
      splitPos = limit;
    }
    parts.push(text.slice(0, splitPos));
    text = text.slice(splitPos);
  }
  if (text) {
    parts.push(text);
  }
  return parts;
}

const textArray = $json["text"];

if (!Array.isArray(textArray)) {
  throw new Error("The input data must contain an array 'text'");
}

const today = new Date();
const formattedDate = today.toLocaleDateString('ru-RU', { 
  day: 'numeric', 
  month: 'long', 
  year: 'numeric' 
}).replace(/\//g, '.');
const header = `📊 *Political digest for ${formattedDate}*\n\n`;

const fullMessage = textArray.join('\n\n');

const messageWithHeader = header + fullMessage;

const chunks = splitMessage(messageWithHeader, 4096);

return chunks.map((chunk, index) => ({ 
  json: { 
    text: chunk,
    part: index + 1,
    total_parts: chunks.length
  } 
}));

const items = $input.all();
return items.map(item => {
  const data = item.json;

  const cleanString = (str) => {
    if (str == null) return '';
    let cleaned = String(str).trim();
    if (cleaned.startsWith('"') && cleaned.endsWith('"')) {
      cleaned = cleaned.slice(1, -1);
    }
    return cleaned;
  };

  const parseArray = (str) => {
    if (!str) return [];
    let cleaned = cleanString(str);

    try {
      const parsed = JSON.parse(cleaned);
      if (Array.isArray(parsed)) return parsed;
    } catch (e) {
    }

    if (cleaned.includes(',')) {
      return cleaned.split(',').map(s => cleanString(s.trim())).filter(Boolean);
    }

    return [cleaned];
  };

  const cleanedData = {
    "creator": cleanString(data.creator),
    "title": cleanString(data.title),
    "link": cleanString(data.link),
    "pubDate": cleanString(data.pubDate),
    "dc:creator": cleanString(data["dc:creator"]),
    "content": cleanString(data.content),
    "contentSnippet": cleanString(data.contentSnippet),
    "guid": cleanString(data.guid),
    "categories": parseArray(data.categories),
    "isoDate": data.isoDate || data["isoDate"]
  };

  const escapedJsonString = JSON.stringify(cleanedData).replace(/"/g, '\"');

  return {
    json: {
      escapedData: escapedJsonString
    }
  };
});

const items = $input.all();

const validItems = items.filter(item => {
  return !item.json.hasOwnProperty('error');
});

return validItems.map(item => {
  const data = item.json;

  if (data.stdout && typeof data.stdout === 'string') {
    try {
      const parsedArticle = JSON.parse(data.stdout);

      return {
        json: parsedArticle
      };
    } catch (e) {
      console.error('Error parsing JSON article:', e);
      return {
        json: data
      };
    }
  }

  return {
    json: data
  };
});

const inputData = $items("Process new articles", 0);

function getCurrentTimestamp() {
  return new Date().toISOString();
}

const processedData = inputData.map(item => {
  const data = item.json;

  return {
    article_url: data.link,
    processed: true,
    publish_date: data.isoDate || getCurrentTimestamp()
  };
});

return processedData.map(item => ({ json: item }));

